    #[cfg(target_os = "linux")]
    #[tokio::test]
    async fn missing_session_bus_resolves_the_installed_x11_helper() {
        const CHILD: &str = "MESH_TALK_SCREENSHOT_PROBE_TEST";
        if let Some(tool) = std::env::var_os(CHILD) {
